#!/usr/bin/env node
'use strict';

/**
 * Angular Component Scaffolder
 *
 * Generates component files (.ts, .html, .scss, .spec.ts) from a name
 * and optional configuration flags.
 *
 * Usage:
 *   node scripts/scaffold-component.js <component-name> [options]
 *
 * Options:
 *   --inputs "name:type,name:type"    Signal inputs to generate
 *   --outputs "name:type,name:type"   Signal outputs to generate
 *   --path <dir>                      Target directory (default: src/app/components/<name>)
 *
 * Output (stdout): JSON  { files: [{ path, content }] }
 * Progress (stderr): human-readable status messages.
 * Exit: 0 on success, 1 on error.
 */

const path = require('path');

// ─── Argument parsing ───────────────────────────────────────
const args = process.argv.slice(2);
const log = (msg) => process.stderr.write(`[scaffold-component] ${msg}\n`);

function option(name, fallback) {
  const idx = args.indexOf(`--${name}`);
  return idx !== -1 && args[idx + 1] ? args[idx + 1] : fallback;
}

const componentName = args.find((a) => !a.startsWith('--'));
if (!componentName) {
  log('ERROR: Component name is required.\n  Usage: node scaffold-component.js <name> [--inputs "n:t"] [--outputs "n:t"] [--path <dir>]');
  process.exit(1);
}

const rawInputs = option('inputs', '');
const rawOutputs = option('outputs', '');
const targetDir = option('path', `src/app/components/${componentName}`);

const inputs = rawInputs ? rawInputs.split(',').map(parseField) : [];
const outputs = rawOutputs ? rawOutputs.split(',').map(parseField) : [];

log(`Scaffolding component: ${componentName}`);
log(`  inputs=${inputs.map((i) => i.name).join(',')}  outputs=${outputs.map((o) => o.name).join(',')}`);
log(`  target=${targetDir}`);

// ─── Helpers ─────────────────────────────────────────────────
function toClassName(name) {
  return name
    .split('-')
    .map((s) => s.charAt(0).toUpperCase() + s.slice(1))
    .join('');
}

function parseField(raw) {
  const [name, type] = raw.trim().split(':');
  return { name: name.trim(), type: (type || 'string').trim() };
}

const className = toClassName(componentName);
const selector = `app-${componentName}`;
const files = [];

// ─── TypeScript component ────────────────────────────────────
function buildComponentTs() {
  const coreImports = ['Component', 'ChangeDetectionStrategy', 'inject'];
  if (inputs.length > 0) coreImports.push('input');
  if (outputs.length > 0) coreImports.push('output');
  coreImports.push('signal');

  const lines = [
    `// ${componentName}.component.ts — generated by scaffold-component`,
    `import {`,
    ...coreImports.map((i) => `  ${i},`),
    `} from '@angular/core';`,
    `import { CommonModule } from '@angular/common';`,
    '',
    `import { LoggingService } from '@core/services/logging.service';`,
    '',
    `/**`,
    ` * ${className} component.`,
    ` *`,
    ` * @remarks`,
    ` * Standalone component with OnPush change detection and signal-based state.`,
    ` */`,
    `@Component({`,
    `  selector: '${selector}',`,
    `  standalone: true,`,
    `  imports: [CommonModule],`,
    `  templateUrl: './${componentName}.component.html',`,
    `  styleUrls: ['./${componentName}.component.scss'],`,
    `  changeDetection: ChangeDetectionStrategy.OnPush,`,
    `})`,
    `export class ${className}Component {`,
    `  private readonly logger = inject(LoggingService);`,
    '',
  ];

  // Signal inputs
  for (const inp of inputs) {
    lines.push(`  /** ${inp.name} input. */`);
    lines.push(`  readonly ${inp.name} = input<${inp.type}>();`);
    lines.push('');
  }

  // Signal outputs
  for (const out of outputs) {
    lines.push(`  /** Emits when ${out.name} changes. */`);
    lines.push(`  readonly ${out.name} = output<${out.type}>();`);
    lines.push('');
  }

  // Internal state
  lines.push(`  /** Internal loading flag. */`);
  lines.push(`  readonly loading = signal(false);`);
  lines.push('}');
  lines.push('');

  files.push({ path: path.join(targetDir, `${componentName}.component.ts`), content: lines.join('\n') });
}

// ─── HTML template ───────────────────────────────────────────
function buildComponentHtml() {
  const lines = [
    `<!-- ${componentName}.component.html — generated by scaffold-component -->`,
    `<section class="${componentName}">`,
    `  <header class="${componentName}__header">`,
    `    <h2>${className}</h2>`,
    `  </header>`,
    '',
    `  @if (loading()) {`,
    `    <div class="${componentName}__loading">Loading…</div>`,
    `  } @else {`,
    `    <div class="${componentName}__content">`,
    `      <!-- Component content goes here -->`,
    `    </div>`,
    `  }`,
    `</section>`,
    '',
  ];

  files.push({ path: path.join(targetDir, `${componentName}.component.html`), content: lines.join('\n') });
}

// ─── SCSS styles ─────────────────────────────────────────────
function buildComponentScss() {
  const lines = [
    `// ${componentName}.component.scss — generated by scaffold-component`,
    `// Uses HDS design tokens for all visual properties.`,
    '',
    `.${componentName} {`,
    `  display: flex;`,
    `  flex-direction: column;`,
    `  gap: var(--hds-spacing-md);`,
    `  padding: var(--hds-spacing-lg);`,
    '',
    `  &__header {`,
    `    border-bottom: 1px solid var(--hds-border-default);`,
    `    padding-bottom: var(--hds-spacing-sm);`,
    '',
    `    h2 {`,
    `      font: var(--hds-font-heading-md);`,
    `      color: var(--hds-text-primary);`,
    `    }`,
    `  }`,
    '',
    `  &__loading {`,
    `    color: var(--hds-text-secondary);`,
    `    font: var(--hds-font-body-sm);`,
    `  }`,
    '',
    `  &__content {`,
    `    min-height: var(--hds-spacing-3xl);`,
    `  }`,
    `}`,
    '',
  ];

  files.push({ path: path.join(targetDir, `${componentName}.component.scss`), content: lines.join('\n') });
}

// ─── Spec file ───────────────────────────────────────────────
function buildComponentSpec() {
  const lines = [
    `// ${componentName}.component.spec.ts — generated by scaffold-component`,
    `import { ComponentFixture, TestBed } from '@angular/core/testing';`,
    `import { ${className}Component } from './${componentName}.component';`,
    `import { LoggingService } from '@core/services/logging.service';`,
    '',
    `describe('${className}Component', () => {`,
    `  let component: ${className}Component;`,
    `  let fixture: ComponentFixture<${className}Component>;`,
    `  let loggerSpy: jasmine.SpyObj<LoggingService>;`,
    '',
    `  beforeEach(async () => {`,
    `    loggerSpy = jasmine.createSpyObj('LoggingService', ['info', 'error', 'warn']);`,
    '',
    `    await TestBed.configureTestingModule({`,
    `      imports: [${className}Component],`,
    `      providers: [`,
    `        { provide: LoggingService, useValue: loggerSpy },`,
    `      ],`,
    `    }).compileComponents();`,
    '',
    `    fixture = TestBed.createComponent(${className}Component);`,
    `    component = fixture.componentInstance;`,
    `    fixture.detectChanges();`,
    `  });`,
    '',
    `  it('should create', () => {`,
    `    expect(component).toBeTruthy();`,
    `  });`,
    '',
    `  it('should default loading to false', () => {`,
    `    expect(component.loading()).toBe(false);`,
    `  });`,
    `});`,
    '',
  ];

  files.push({ path: path.join(targetDir, `${componentName}.component.spec.ts`), content: lines.join('\n') });
}

// ─── Main ────────────────────────────────────────────────────
buildComponentTs();
buildComponentHtml();
buildComponentScss();
buildComponentSpec();

log(`Generated ${files.length} file(s)`);
process.stdout.write(JSON.stringify({ files }, null, 2) + '\n');
